parameters.query:
SELECT insight_id, business_id, week_start, week_end, narrative, metrics,
  'http://localhost:5678/webhook/vaibhavcapstone-insights-latest?business_id=' || business_id AS report_url
FROM vaibhavcapstone_insights WHERE business_id = $1 ORDER BY created_at DESC LIMIT 1;

parameters.jsCode:
const b = ($input.first().json.body) || {};
const S = {
  hot: { subject: 'Urgent bulk order for our new office', body: 'Hi, we are fitting out a new office and need around 30 units delivered within three weeks. Our budget is about Rs. 6,00,000. Can you quote?\n\nRavi Kapoor\nOperations Head, Northwind Labs' },
  warm: { subject: 'Exploring options', body: 'Hello, we are comparing options for our home and would like to see what you have available. No rush.\n\nSuchitra' },
  spam: { subject: 'CONGRATULATIONS!! You have WON', body: 'Dear winner, send your bank details and a processing fee to claim your prize IMMEDIATELY.' },
  vendor: { subject: 'Partnership proposal - raw material supply', body: 'Greetings, we are a leading supplier and would like to become your vendor. Please find our rate card attached.' }
};
const key = String(b.scenario || 'hot').toLowerCase();
const custom = b.body && String(b.body).trim();
const s = custom ? { subject: String(b.subject || 'Customer enquiry (test)'), body: String(b.body) } : (S[key] || S.hot);
return [{ json: { business_id: b.business_id, channel: 'mcp-test', from_email: b.from_email || ('test.customer+' + key + '@example.com'),
  from_name: String(b.from_name || 'Test Customer'), subject: s.subject, body: s.body, external_id: 'mcp-test-' + Date.now(), scenario: key } }];
